args.streamContent:
CREATE SCHEMA IF NOT EXISTS app;

-- Range-partitioned by calendar month on created_at for partition pruning on date filters.
CREATE TABLE app.events (
  id BIGSERIAL,
  created_at TIMESTAMPTZ NOT NULL,
  event_type TEXT NOT NULL,
  payload JSONB DEFAULT '{}'
) PARTITION BY RANGE ((created_at AT TIME ZONE 'UTC'));

CREATE TABLE app.events_2026_01 PARTITION OF app.events
  FOR VALUES FROM ('2026-01-01') TO ('2026-02-01');

CREATE TABLE app.events_2026_02 PARTITION OF app.events
  FOR VALUES FROM ('2026-02-01') TO ('2026-03-01');

CREATE TABLE app.events_default PARTITION OF app.events DEFAULT;

CREATE INDEX idx_events_created_at ON app.events (created_at);

INSERT INTO app.events (created_at, event_type, payload)
SELECT
  '2026-01-01'::timestamptz + (i || ' hours')::interval,
  (ARRAY['pageview', 'click', 'purchase'])[1 + (i % 3)],
  '{}'::jsonb
FROM generate_series(0, 719) AS i;

